mapper.sql:
where p.is_deleted = 'N' and p.board_type = #{boardType}
and p.category = #{category}
and upper(p.title) like '%' || upper(#{kw}) || '%' escape '\'
and upper(p.content) like '%' || upper(#{kw}) || '%' escape '\'
and upper(m.nickname) like '%' || upper(#{kw}) || '%' escape '\'
and (upper(p.title) like '%' || upper(#{kw}) || '%' escape '\' or upper(p.content) like '%' || upper(#{kw}) || '%' escape '\')

mapper.select:
select post_seq, board_type, category, title, view_count, recommend_count, comment_count, created_at, writer_name
  from (
	select rownum as rnum, t.*
	  from (
		select p.post_seq, p.board_type, p.category, p.title, p.view_count, p.recommend_count,
		       p.comment_count, p.created_at,
		       case when p.board_type = 'ANON' then '익명' else m.nickname end as writer_name
		  from post p
		  join member m on p.member_seq = m.member_seq

		 order by p.post_seq desc
	  ) t
	 where rownum <= #{endRow}
  )
 where rnum >= #{startRow}

mapper.update:
update post
   set is_deleted = 'Y',
       deleted_at = systimestamp
 where post_seq = #{postSeq}
   and member_seq = #{memberSeq}
   and is_deleted = 'N'
